# Hotfix: party invites. Every GET /invites (and every decline) failed since v106 because 'dec' is a DynamoDB
# reserved word (~2,000-3,000 errors per 6 h in CloudWatch). Paste into AWS CloudShell (us-east-1). Needs John's go.
set -e
TS=$(date +%Y%m%d%H%M); mkdir -p ~/lhbak ~/lhinv && cd ~/lhinv
curl -s "$(aws lambda get-function --function-name lanternhold-invite --query Code.Location --output text)" -o ~/lhbak/lanternhold-invite-$TS.zip
echo "backup: ~/lhbak/lanternhold-invite-$TS.zip"
echo  | base64 -d > index.js && rm -f invite.zip && zip -qj invite.zip index.js
aws lambda update-function-code --function-name lanternhold-invite --zip-file fileb://invite.zip >/dev/null
aws lambda wait function-updated --function-name lanternhold-invite
sleep 90
aws cloudwatch get-metric-statistics --namespace AWS/Lambda --metric-name Errors --dimensions Name=FunctionName,Value=lanternhold-invite --start-time $(date -u -d '-3 minutes' +%FT%TZ) --end-time $(date -u +%FT%TZ) --period 60 --statistics Sum --query 'Datapoints[].Sum' --output text
echo "done (errors per minute above should drop to 0). Undo: aws lambda update-function-code --function-name lanternhold-invite --zip-file fileb://$HOME/lhbak/lanternhold-invite-$TS.zip"
